# notes_server.py   (pip install "mcp[cli]")
from mcp.server import MCPServer

mcp = MCPServer("Notes")
NOTES = {"groceries": "milk, eggs", "ideas": "MCP talk"}


@mcp.tool()
def list_notes() -> list[str]:
    """List the titles of all notes."""
    return sorted(NOTES)


@mcp.resource("notes://{title}")
def read_note(title: str) -> str:
    """The text of one note."""
    return NOTES[title]


@mcp.prompt()
def summarize(title: str) -> str:
    """Summarize one note."""
    return f"Summarize this note in one sentence:\n\n{NOTES[title]}"


if __name__ == "__main__":
    mcp.run()          # stdio by default

from pydantic import BaseModel
from mcp.server import MCPServer
from mcp.server.mcpserver.exceptions import ToolError

mcp = MCPServer("Notes")
NOTES = {"groceries": "milk, eggs"}


class Note(BaseModel):
    title: str
    body: str
    words: int


@mcp.tool()
def get_note(title: str) -> Note:
    """Return one note by its exact title."""
    if title not in NOTES:
        raise ToolError(f"No note {title!r}. Known titles: {sorted(NOTES)}")
    body = NOTES[title]
    return Note(title=title, body=body, words=len(body.split()))

