import json
from mcp.server import MCPServer

mcp = MCPServer("Shop")
PRODUCTS = {"p1": {"name": "Mug", "price": 12}}


@mcp.resource("shop://products", mime_type="application/json")
def products() -> str:
    """All products as JSON."""
    return json.dumps(PRODUCTS)


@mcp.resource("shop://products/{product_id}")
def product(product_id: str) -> str:
    """One product, as readable text."""
    p = PRODUCTS[product_id]
    return f"{p['name']}: ${p['price']}"

