from typing import Annotated
from pydantic import Field
from mcp.server import MCPServer
from mcp.server.mcpserver.prompts.base import AssistantMessage, UserMessage

mcp = MCPServer("Code Helper")


@mcp.prompt(title="Code review")
def review_code(
    code: Annotated[str, Field(description="The code to review")],
    language: str = "python",
) -> str:
    """Review code for bugs, readability and tests."""
    return f"Review this {language} code. List bugs first, then style issues:\n\n{code}"


@mcp.prompt()
def debug_error(error: str) -> list:
    """Start a debugging conversation about an error message."""
    return [
        UserMessage(f"I'm seeing this error:\n{error}"),
        AssistantMessage("Let's debug it. What changed right before it started?"),
    ]

