import pytest
from mcp import Client
from notes_server import mcp


@pytest.fixture
def anyio_backend():
    return "asyncio"


@pytest.fixture
async def client():
    async with Client(mcp, raise_exceptions=True) as c:
        yield c


@pytest.mark.anyio
async def test_tools_are_listed(client: Client):
    names = {t.name for t in (await client.list_tools()).tools}
    assert names == {"list_notes"}


@pytest.mark.anyio
async def test_list_notes(client: Client):
    result = await client.call_tool("list_notes", {})
    assert not result.is_error
    assert result.structured_content == {"result": ["groceries", "ideas"]}

